Definition hidden (P : Prop) : Prop := P.
Lemma hide : forall P : Prop, P -> hidden P. Proof. exact (fun P p => p). Qed.
Ltac hideH H := apply hide in H.
Ltac showH H := unfold hidden in H.
(* [comment removed for export] *)
Ltac notrap_h H := showH H; notrap; hideH H.

(* [comment removed for export] *)
Lemma nullalign_and : forall p, 0 < p -> p mod 8 = 0 -> Z.land (Z.b2z (0 <? p)) (Z.b2z (Z.land p 7 <? 1)) = 1.
Proof.
  intros p P A. rewrite land7_mod8, A. replace (0 <? p) with true by (symmetry; apply Z.ltb_lt; lia). reflexivity.
Qed.

(* [comment removed for export] *)
Lemma nullbase_xor : forall b s, (0 < b /\ 0 < s) \/ (b = 0 /\ s = 0) -> Z.lxor (Z.b2z (0 <? b)) (Z.b2z (s <? 1)) = 1.
Proof.
  intros b s Hb. destruct (Z.ltb_spec 0 b); destruct (Z.ltb_spec s 1); cbn; first [reflexivity | exfalso; lia].
Qed.

